    timezone: 'CST',
    description:
      'Every Tuesday at 10:30 a.m., toddlers and their caregivers are invited to explore Hank the Cowdog’s M-Cross Ranch at the Cash Family Ranch Life Learning Center. Hosted by the National Ranching Heritage Center, Toddler Tuesdays offer fun, free activities such as story time and crafts led by staff and volunteers. Children can also enjoy imaginative play in Sally Mae’s Ranch House, filled with ranch-themed toys from the Happy Toymaker.',
