    timezone: 'CST',
    description:
      'The First Friday Art Trail (FFAT) is a free, self-guided art event held in the Lubbock Cultural District that features a vibrant mix of art centers, museums, galleries, and local businesses. Visitors can enjoy live music, food trucks, and artwork from local, national, and international artists. Detailed event listings and maps are available on the official website at ffat.org. FFAT is a program of LHUCA, made possible through grants from the City of Lubbock, Civic Lubbock, Inc., the Texas Commission on the Arts, the National Endowment for the Arts, The CH Foundation, and The REA Charitable Trust.',
