    description:
      'Get ready for Cotton Fest 2025, happening June 26–28 at Cook’s Garage! This epic weekend celebration features live music, mechanical bull riding, casino night, goat roping, and more—all benefiting the High Cotton Relief Fund. It’s a rain-or-shine event with a $20 fee for coolers over 4 quarts, and only designated areas allow coolers and wagons (no glass or outside food permitted). BYOB is welcome, but weapons—including pocket knives—are prohibited. Bring your own lawn chairs (unbagged for security checks), and note that professional photography requires prior approval. Tickets are final sale with no refunds. Don’t miss out on this unforgettable weekend full of music, fun, and community spirit!',
