    id: '57649f01-04ed-4617-e86f-dba2b4a77fd5',
    name: 'Ranch Verse: Poetry, Song & Storytelling',
    title: 'Ranch Verse: Poetry, Song & Storytelling',
    startTime: '2025-08-02T15:30:00.000Z',
    endTime: '2025-08-03T03:00:00.000Z',
    timezone: 'CDT',
    description:
      '<div class="xdj266r x11i5rnm xat24cr x1mh8g0r x1vvkbs">Join cowboy songster, Andy Hedges, for a day of Western storytelling, song and poetry at the 3rd annual Ranch Verse on Saturday, Aug. 2 in Lubbock, TX!</div> \r\n <div class="x11i5rnm xat24cr x1mh8g0r x1vvkbs xtlvy1s">Daytime events with special guests, Hal Cannon, Dom Flemons, Pipp Gillette and Joel Nelson will occur from 10:30 a.m. – 4:30 p.m. at the National Ranching Heritage Center and are free to the public. Enjoy special performances, poetry readings and discussions, and an onstage interview with Ranching Heritage Association Working Cowboy Award recipient, Joel Nelson, for Western podcast, Cowboy Crossroads.</div> \r\n <div class="x11i5rnm xat24cr x1mh8g0r x1vvkbs xtlvy1s">A special evening performance at the historic Cactus Theater (ticketed event) will take place from 7:30 – 10 p.m. with Andy Hedges, Dom Flemons and Pipp Gillette. Tickets for the evening concert are on sale now. <div class="x1i10hfl xjbqb8w x1ejq31n xd10rxx x1sy0etr x17r0tee x972fbf xcfux6l x1qhh985 xm0m39n x9f619 x1ypdohk xt0psk2 xe8uvvx xdj266r x11i5rnm xat24cr x1mh8g0r xexx8yu x4uap5 x18d9i69 xkhd6sd x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz xkrqix3 x1sur9pj xzsf02u x1s688f" role="button" tabindex="0"></div> \r\n </div> \r\n ',
    hostLink: 'https://en-gb.facebook.com/nrhcttu',
