    description:
      'For over 22 years, the Flatland Film Festival has showcased a diverse range of films, including short films, feature films, documentaries, animations, music videos, and video art. The festival’s programming aims to evoke emotion, challenge perspectives, and highlight the power of visual storytelling, enriching cultural conversations in Lubbock and beyond. In 2025, the festival will accept short film submissions from all genres and feature film submissions specifically highlighting stories from Texas and the Southwest, with one feature film selected for the festival. Visit the Flatland Film Festival website for submission details and deadlines.',
