    name: 'Blue Man Group',
    title: 'Blue Man Group',
    startTime: '2026-03-21T19:00:00.000Z',
    endTime: null,
    timezone: 'CDT',
    description:
      'Tickets for the 2025–2026 Broadway season are currently available exclusively through season memberships. Single tickets will go on sale in Fall 2025. Blue Man Group performances are a celebration of human connection. Mixing art, music, comedy, and state-of-the-art technology, the show encourages audiences to reconnect with their inner (and outer) child and see the world through a new perspective. Three bald and blue men explore our cultural norms with wide-eyed wonder, poking fun at our collective quirks and reminding us how much we all have in common. Blue Man Group is not just a show featuring three bald and blue men, it’s a total immersive experience. The Blue Man is thought of as an “everyman” who holds a mirror up to us and our culture, helping us laugh at ourselves and see the world differently. The real goal of any Blue Man Group show is to celebrate all that we have in common as human beings—to celebrate our curiosity, creativity, and need for community.',
