    description:
      '<div class="xdj266r x11i5rnm xat24cr x1mh8g0r x1vvkbs">Murder and blackmail are on the menu when six mysterious guests assemble at Boddy Manor for a night they’ll never forget! Based on the fan-favorite 1985 Paramount Pictures movie and inspired by the classic Hasbro board game, Clue is the ultimate whodunit that will leave you dying of laughter and keep you guessing until the final twist.</div> \r\n <div class="x11i5rnm xat24cr x1mh8g0r x1vvkbs xtlvy1s">©2025 Hasbro All Rights Reserved</div> \r\n <div class="x11i5rnm xat24cr x1mh8g0r x1vvkbs xtlvy1s">Ages 12+ Recommended <div class="x1i10hfl xjbqb8w x1ejq31n xd10rxx x1sy0etr x17r0tee x972fbf xcfux6l x1qhh985 xm0m39n x9f619 x1ypdohk xt0psk2 xe8uvvx xdj266r x11i5rnm xat24cr x1mh8g0r xexx8yu x4uap5 x18d9i69 xkhd6sd x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz xkrqix3 x1sur9pj xzsf02u x1s688f" role="button" tabindex="0"></div> \r\n </div> \r\n ',
