    id: 'd058f228-1570-015d-9f93-d6b0d1c2e37d',
    name: 'Spring Trolley Tours',
    title: 'Spring Trolley Tours',
    startTime: '2025-05-18T19:30:00.000Z',
    endTime: '2025-05-31T20:15:00.000Z',
    timezone: 'CDT',
    description:
      'Travel back in time through the National Ranching Heritage Center’s 19-acre historical park! Trolley tours provide a unique opportunity for guests to learn about the rich history of the park’s authentic ranching structures and the stories of the people who left their legacies. The Foy Proctor Historical Park at the NRHC features 55 authentic ranching structures dating from the 1780s to the 1950s, which have been disassembled, relocated, and arranged chronologically to tell the story of the birth, growth, and maturity of the ranching industry in the United States. Tours run from April 9 through May 31 (weather permitting) on Wednesdays, Thursdays, and Fridays at 2:30 p.m.; Saturdays at 10:30 a.m. and 2:30 p.m.; and Sundays at 2:30 p.m. The tours are free of charge, last approximately 45 minutes, and seat up to 21 guests per trolley. Guests should reserve their spot at the front desk upon arrival. For more information, visit ranchingheritage.org or call (806) 742-0498. The trolley tours are made possible by The CH Foundation through the donation of the trolley.',
