    timezone: 'CDT',
    description:
      'McPherson Cellars presents Live Music Nights every other Thursday from 6 to 9 PM, running May through August. Enjoy live performances by local musicians, discounted wines by the glass, and a rotating lineup of tasty food trucks. Events will be held indoors in the Event Center to ensure comfort regardless of the West Texas weather, while the courtyard remains open. The 2025 schedule includes acts like ‘806 Duo,’ D.G. Flewellyn, Jeremy Couture, Jere Lowe, Mark Wallney, Anthony Garcia & Friends, Jenni Dale Lord, Philip Coggins, and Spivey, with food trucks such as Llano Cubano, Lonestar Mac Dough, Mijo’s, Rolling Wood Fire Pizza, Nirvana Burger, and Crusty’s Woodfire Pizza. It’s a perfect way to enjoy great music, delicious food, and excellent wine in a welcoming atmosphere.',
