    timezone: 'CST',
    description:
      'First Friday Art Trail (FFAT), a program of LHUCA, is a free, self-guided art event held in the Lubbock Cultural District. In partnership with local art centers, museums, galleries, and businesses, FFAT offers live music, food trucks, and art from local, national, and international artists. Detailed listings and maps of all official venues and events can be found at ffat.org. This program is made possible in part through grants from the City of Lubbock, Civic Lubbock, Inc., Texas Commission on the Arts, National Endowment for the Arts, The CH Foundation, and The REA Charitable Trust.',
