    endTime: null,
    timezone: 'CDT',
    description:
      'Get ready for an unforgettable evening of music, laughter, and award-winning wine at Dueling Pianos Night! This electrifying experience features two pianists going head-to-head in a lively musical battle, full of fast-paced melodies, playful improvisation, and spontaneous entertainment. From the first note, the energy is contagious. Gather your friends and sing along to a night filled with fun and excitement. Whether you’re celebrating a special occasion or just looking for a memorable night out, this is one event you won’t want to miss!',
