    endTime: null,
    timezone: 'CDT',
    description:
      'Experience an unforgettable evening of timeless music with Piano Men: Generations on Friday, August 15, 2025, at The Buddy Holly Hall. Doors open at 7:00 PM for a night filled with the legendary hits of Billy Joel and Elton John, performed by the talented father-son duo, Terry and Nick Davies. This dynamic show celebrates decades of iconic piano-driven rock with powerful vocals, dueling pianos, and heartfelt storytelling. For tickets or more information, contact the Buddy Holly Hall Box Office at boxoffice@buddyhollyhall.com or call (806) 792-8339. Tickets are available at etix.com. Don’t miss this multigenerational tribute to two of music’s greatest legends!',
