    description:
      'Step into the whimsical chaos of the Feast of Fools at the Third Annual Hub City Renaissance Faire! This lively medieval tradition tosses aside rules and flips societal norms in a whirlwind of laughter, mischief, and colorful celebration. Everyone—from jesters to nobles—is invited to join in spontaneous performances, quirky games, and a joyous embrace of life’s absurdity. Dress for the feast by channeling extravagant costumes with bold, mismatched patterns, feathered hats, cap and bells, or quirky props like juggling balls. Whether you come as a jester, mischievous clown, or disguised royalty, the more outrageous the better! Interested vendors should stay tuned for details, and please note that all official payment requests will come only from LHUCA via email—never through social media or unrelated addresses.',
