    endTime: null,
    timezone: 'CST',
    description:
      'Tickets for the 2025–2026 Broadway season are currently available exclusively through season memberships, with single tickets going on sale in Fall 2025. Water for Elephants, a critically acclaimed new musical adapted from Sara Gruen’s bestselling novel, has been hailed as “stunning, emotional, heart-filled and gorgeously imaginative” by The New York Times. Directed by Tony Award nominee Jessica Stone, with a book by three-time Tony nominee Rick Elice and a soaring score by PigPen Theatre Co., the production tells the story of a young man who, after losing what matters most, joins a traveling circus and discovers a new life and love beyond his wildest dreams. Praised for its “spellbinding entertainment” (Variety), Water for Elephants is celebrated as “the best new musical on Broadway” (Theatermania).',
