    description:
      "Tickets for the 2025–2026 Broadway season are currently available exclusively through season memberships. Single tickets will go on sale in Fall 2025. A new musical comedy about the things we do to stay together. Everyone’s favorite Scottish nanny is headed to Lubbock in this internationally acclaimed hit musical critics call 'wonderful, heart-warming, and laugh-out-loud funny' (Manchester Evening News) and 'a feel-good, family-friendly comedy that delivers' (The Hollywood Reporter). Based on the beloved film, MRS. DOUBTFIRE tells the hysterical and heartfelt story of an out-of-work actor who will do anything for his kids. It’s 'the lovable, big-hearted musical comedy we need right now,' raves the Chicago Tribune – one that proves we’re better together.",
