    "id": "",
    "name": "Celebrate AAPI at CMOA",
    "title": "Celebrate AAPI at CMOA",
    "description": "Set off on a journey through the Pacific Islands while armed with the legendary IMAGI-TOOL 2000 (a.k.a. a pool noodle). Kids will use their imaginations to row boats, scale mountains and escape volcanoes—learning about the vibrant flora, fauna and geography of the Pacific Islands along the way. Also, on stage will be a retelling of a classic fable, “Little Red Riding Hood and the Dragon” by Ying Chang Compenstine. Little ones can build skyscrapers in Jane’s Innovation Station, discovering which can withstand the forces of weight, wind and even an earthquake. Dive into the invisible world of viruses and vaccines at the Science Bar while learning about Chinese-American scientist Dr. Flossie Wong-Staal. In the Art Studio, future Picassos create a bug inspired by the work of Japanese artist Hiroshi Shinno!",
    "category": "Local Attractions",
