    "name": "Free Self-guided Street Art Walking Tours",
    "title": "Free Self-guided Street Art Walking Tours",
    "description": "Atlanta is one of the best cities in the US for street art. Take a free self-guided street art walking tour on your own smart device any day any time. There are tours available in the following 9 neighborhoods: Atlanta Beltline, Cabbagetown, Castleberry Hill & S.W. Downtown, East Atlanta, Edgewood Avenue, Little Five Points, Pittsburgh neighborhood, Ralph David Abernathy Blvd., and West End. This is a great way to get your steps in, explore Atlanta's neighborhoods, and see an aspect of Atlanta that even most natives miss. The interactive on-line maps will guide you on a treasure hunt to jaw-dropping works of art in obscure locations that you might never notice just walking down the street.",
