    "name": "Beginner’s Salsa Lessons @ PasoFino Dance Studio",
    "title": "Beginner’s Salsa Lessons @ PasoFino Dance Studio",
    "description": "Ready to dance and mingle? Our class is all about dancing with others and making connections. We teach the fundamentals of dance while switching partners every five minutes. Come alone or as a couple, choose to be a lead or a follow, and enjoy a relaxed lesson with new friends.\n\nThis class is for absolute beginners who want to learn the basics of partner dancing and make some new friends. Very laid-back atmosphere.\n\n> MONDAY - 7pm - Salsa Beg 0\n> WEDNESDAY - 7pm - Bachata Beg 0\n> THURSDAY - 8pm - Salsa Beg 0\n\nMore information @ https://www.pasofinodance.com",
