    "name": "Amanda Williams: We Say What Black This Is",
    "title": "Amanda Williams: We Say What Black This Is",
    "description": "Spelman College Museum of Fine Art presents We Say What Black This Is, an exhibition showcasing mixed media and watercolor paintings by MacArthur award-winning artist Amanda Williams. The new exhibit opens February 7, 2025, and will be on view through May 24, 2025.\n\nWe Say What Black This Is celebrates the diversity, resilience and depth of Blackness while challenging simplistic definitions of Black identity. The exhibition features works from Williams' series What Black is this, You Say?, created in response to the ‘Blackout Tuesday’ social media moment in 2020. The exhibit will include a new abstract painting by Williams and student-written didactic labels.",
    "category": "Local Attractions",
