    "title": "More Than Brave: The Life of Henry Aaron",
    "description": "More Than Brave tells the story of Henry Aaron from his time in Mobile, Alabama, to his record making baseball career and his life as a leader in baseball, business, and charitable causes. The exhibition features images and artifacts from the collections of the Aaron family, Atlanta History Center, the Atlanta Braves, the National Baseball Hall of Fame, Emory University, Negro Leagues Baseball Museum, and personal collections from throughout the United States.",
