    "name": "Barks and Bites: Doggie Crawl on the Beltline",
    "title": "Barks and Bites: Doggie Crawl on the Beltline",
    "description": "Treat your dog to a day out on the Atlanta Beltline with dining, shopping, and socializing at dog-friendly spots! On this unique crawl, your furry foodie can savor gourmet meals crafted just for them at some of Atlanta's most dog-friendly restaurants, and enjoy puptail hour with “Barkaritas.\" You’ll also stop at pet boutiques so your fur baby can pick out toys and treats, take home swag bags filled with goodies, and support local animal rescues with each ticket. It’s the perfect way to return your pup’s unconditional love with a day of fun and pampering. Celebrating your dog’s birthday? Choose the “Barkday Pawty Pack” when booking for a fun, personalized experience.",
