    "name": "Endless Sunday Brunch Buffet",
    "title": "Endless Sunday Brunch Buffet",
    "description": "Starting Sunday, May 18th, 5Church Midtown launches its Endless Sunday Brunch Buffet—an all-you-can-eat experience for $45 adults / $20 kids. Enjoy chef-attended carving stations, made-to-order omelets, fresh salads, pastries, and more in our stylish main dining room. Add bottomless mimosas for $30. Served Sundays with a 2-hour limit per table. Dine-in only—no to-go. Reservations strongly encouraged via Resy. Brunch season starts now—join us every Sunday!",
