    "description": "Registration is OPEN at JoinPickleball.com. JOIN Pickleball Leagues – Play at ITP Training Academy or choose your Home Court for Flex Leagues or Monday Team Challenge Leagues. Registration is OPEN through JUNE 16. Must SIGN-UP to play. Atlanta TEAM CHALLENGE Leagues: Our Award-Winning Team-Based Leagues are the ultimate pickleball experience – fun, engaging, and socially competitive! This league is for teams of 8-10 players. Choose to play on Mondays (must have at least 2 reservable Home Courts for Home matches) or play on Thursdays at ITP Training Academy. THURSDAY TEAM CHALLENGE @ ITP Training Academy: Full-service Pickleball Leagues.",
