    "name": "Signs of the Times: The Changing Face of Football",
    "title": "Signs of the Times: The\nChanging Face of Football",
    "description": "The College Football Hall of Fame recently unveiled its newest limited-time exhibit, which offers visitors an inside look into the complex history of on-field communication devices. Titled “Signs of the Times,” the exhibit is an immersive experience that explores the evolution of how coaches communicate with their team on the field, from early face-to-face instructions and hand signals, to today’s high-tech innovations.\n\nSome highlights of the exhibit include:\n\n- A Transparent Football Helmet displaying Coach-to-Player Receivers on loan from CoachComm\n- An entire X-System Sideline Cart on loan from CoachComm\n- Interactive Playboard Game for fans to guess the play call\n\nThe exhibit is currently available through the month of May, and can be found on the second floor of the Hall of Fame, in the Andrea & James Clarke Family Gallery.",
