    "name": "HBCU Scholarship Opportunity with The Hall",
    "title": "HBCU Scholarship\nOpportunity with The Hall",
    "description": "The Chick-fil-A College Football Hall of Fame is proud to announce the continuation of its partnership with Kia America’s “Accelerate the Good” program to offer scholarships for the upcoming academic year.\n\nAfter successfully providing financial aid to five outstanding individuals last year, the program is again looking to fund five scholarships of $5,000 each to high school seniors planning to attend or students currently enrolled at a Historically Black College and University.\n\nVisit the Hall of Fame website for more details. Applications will be accepted through May 31, 2025.",
